const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // A rectangular geometry covering the core of the Adirondack Mountains.
    const adirondacks = ee.Geometry.Rectangle([-75.3, 43.3, -73.3, 44.9]);
    const date1 = '2022-10-01';
    const date2 = '2022-10-08';

    // 2. Data Acquisition and Processing Logic
    const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

    // Function to mask clouds, shadows, and water using the SCL band.
    // We keep vegetation (4), bare soil (5), and unclassified (7) to focus on land cover.
    function maskS2CloudsAndWater(image) {
        const scl = image.select('SCL');
        const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(7)); // Keep vegetation, bare soils, unclassified
        return image.updateMask(mask);
    }

    // Function to calculate NDVI.
    function addNDVI(image) {
        const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
        return image.addBands(ndvi);
    }

    // Function to process an image for a specific date.
    const processDate = (dateString) => {
        const startDate = ee.Date(dateString);
        const endDate = startDate.advance(1, 'day');

        let imageCollection = s2Collection
            .filterBounds(adirondacks)
            .filterDate(startDate, endDate)
            .map(maskS2CloudsAndWater)
            .map(addNDVI);

        // Check if the collection is empty
        if (imageCollection.size().getInfo() === 0) {
            return { image: null, count: 0, cloud_percent: 'N/A' };
        }

        const mosaic = imageCollection.mosaic();

        // Calculate cloud cover before masking for reporting
        const originalCollection = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
            .filterBounds(adirondacks)
            .filterDate(startDate, endDate);
        const cloudProb = ee.Image(originalCollection.first()).select('probability');
        const cloudStat = cloudProb.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: adirondacks,
            scale: 3000,
            maxPixels: 1e9
        });
        const cloudPercent = cloudStat.get('probability').getInfo();


        // Check for valid pixels after masking
        const pixelCount = mosaic.select('NDVI').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: adirondacks,
            scale: 3000,
            maxPixels: 1e9
        }).get('NDVI').getInfo();

        return { image: mosaic, count: pixelCount, cloud_percent: cloudPercent };
    };

    // 3. Process data for both dates
    const result1 = processDate(date1);
    const result2 = processDate(date2);

    if (result1.count === 0 || result2.count === 0) {
        console.log(`Valid pixel count for ${date1}: ${result1.count}`);
        console.log(`Valid pixel count for ${date2}: ${result2.count}`);
        if(result1.image === null || result2.image === null) {
            console.log('Evidence: No images found for one or both dates.');
            console.log('A'); // Fallback: Fall foliage progresses rapidly, so later date is likely browner.
        } else {
            console.log('Evidence: No valid pixels remained after cloud/water masking.');
            console.log('C2');
        }
        return;
    }

    // 4. Calculation
    // Lower NDVI suggests less green, more "brown/orange" vegetation.
    const meanNdvi1 = result1.image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: adirondacks,
        scale: 3000,
        maxPixels: 1e9
    }).get('NDVI');

    const meanNdvi2 = result2.image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: adirondacks,
        scale: 3000,
        maxPixels: 1e9
    }).get('NDVI');

    const ndviVal1 = meanNdvi1.getInfo();
    const ndviVal2 = meanNdvi2.getInfo();

    // 5. Validation & Final Answer
    if (ndviVal1 === null || ndviVal2 === null) {
        console.log('Evidence: NDVI calculation failed, resulting in a null value.');
        console.log('C3');
        return;
    }

    console.log(`Date: ${date1}, Mean NDVI: ${ndviVal1.toFixed(4)}, Initial Cloud Prob: ${result1.cloud_percent.toFixed(2)}%`);
    console.log(`Date: ${date2}, Mean NDVI: ${ndviVal2.toFixed(4)}, Initial Cloud Prob: ${result2.cloud_percent.toFixed(2)}%`);
    console.log(`Evidence: Mean NDVI decreased from ${ndviVal1.toFixed(4)} to ${ndviVal2.toFixed(4)}.`);
    console.log('A lower NDVI indicates less healthy (more brown/orange) vegetation.');

    if (ndviVal2 < ndviVal1) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
